package com.franco.desco.adapter.in.web.salesoperation;import io.swagger.v3.oas.annotations.media.Schema;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class SalesOperationResponses{private SalesOperationResponses(){}@Schema(name="SalesOperationCreatedResponse")public record Created(Long operativoVentaId){}@Schema(name="SalesOperationSummaryResponse")public record Summary(Long operativoVentaId,Long campaniaVentaId,String campania,String codigo,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,Integer cantidadJabasRecibidas,Long jabasAsignadas,Long jabasDevueltas,Long jabasDisponibles,Long jabasPendientes,BigDecimal kilosRecibidos,BigDecimal kilosAceptados,BigDecimal kilosRechazados,String estadoProceso,String observacion,Long participantes,Long entregas,Long incidenciasPendientes){}@Schema(name="SalesOperationHeaderResponse")public record Header(Long operativoVentaId,String codigo,Long campaniaVentaId,String campania,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,String estadoProceso,String observacion,Integer jabasRecibidas,Integer jabasAsignadas,Integer jabasDevueltas,Integer jabasPendientes,Integer jabasDisponibles){}@Schema(name="SalesOperationZoneResponse")public record Zone(Long zonaProductivaId,String codigo,String nombre){}@Schema(name="SalesOperationParticipantResponse")public record Participant(Long operativoSocioId,String estadoParticipacion,Long participacionId,String numeroDocumento,String socioNombre){}@Schema(name="SalesOperationDeliveryResponse")public record Delivery(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String estadoProceso){}@Schema(name="SalesOperationIncidentResponse")public record Incident(Long incidenciaId,String tipoIncidencia,String severidad,String descripcion,String estadoIncidencia){}@Schema(name="SalesOperationDetailResponse")public record Detail(Header operativo,List<Zone>zonas,List<Participant>participantes,List<Delivery>entregas,List<Incident>incidencias){} }
